// TODO - update highlights to be more readable for the user
#[derive(PartialEq)]
pub enum StitchCommand {
    /// # Definition
    /// Inc(n) means put n stitches at the current pointer,
    /// and then move the current pointer one across.
    /// 
    /// # Useful identities
    /// * Inc(1) === sc === Dec(0)
    /// * Inc(0) === Skip(1)
    Inc(usize, Vec<Highlight>),
    /// # Definition
    /// Dec(n) means to put a stitch at the current pointer,
    /// then move the current pointer n + 1 across, such that
    /// there are n empty stitches between the two positions.
    /// 
    /// # Useful identities
    /// * Dec(0) === sc === Inc(1)
    Dec(usize, Vec<Highlight>),
    /// # Definition
    /// Skip(n) means do NOT put a stitch at the current pointer.
    /// Instead move it across n stitches (such that there are
    /// n - 1 empty stitches between the two positions).
    /// 
    /// # Useful identities
    /// * Skip(0) === "do nothing"
    /// * Skip(1) === "move to the next stitch"
    /// * sc + Skip(n) === Dec(n)
    /// * Dec(n) + Skip(m) === Dec(n + m)
    /// 
    /// # Note that
    /// This can only occur after an Inc (of magnitude >= 2),
    /// so identifies an Inc-Dec pair.
    /// Dec-Inc pairs can be represented fine.
    #[allow(unused)] // Allow because we might revert back to how it was handled previously.
    Skip(usize, Vec<Highlight>),
    /// # Definition
    /// MagicCircle(n) means create a magic circle with n
    /// stitch points. Do not yet connect off the ends of
    /// this magic circle, as this is handled by NextRow.
    MagicCircle(usize, Vec<Highlight>),
    /// # Definition
    /// Connect the end of the last stitch to the end of the chain,
    /// move the pointer to the next row, at the seam,
    /// and replace the next supposed stitch into a chain.
    NextRow(Vec<Highlight>),
}

impl Debug for StitchCommand {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Inc(n, _) => write!(f, "Inc{n}"),
            Self::Dec(n, _) => write!(f, "Dec{n}"),
            Self::Skip(n, _) => write!(f, "Skip{n}"),
            Self::MagicCircle(n, _) => write!(f, "MagicCircle{n}"),
            Self::NextRow(_) => write!(f, "NextRow"),
        }
    }
}

impl StitchCommand {
    pub fn get_highlights(&self) -> &Vec<Highlight> {
        match self {
            Self::Inc(_, highlights) => highlights,
            Self::Dec(_, highlights) => highlights,
            Self::Skip(_, highlights) => highlights,
            Self::MagicCircle(_, highlights) => highlights,
            Self::NextRow(highlights) => highlights,
        }
    }
}

#[derive(PartialEq, Debug, Clone, Copy)]
enum MoveStitch {
    Curr,
    Next
}

#[derive(Clone, Copy)]
struct Move {
    stitch: MoveStitch,
    highlight: Highlight,
}

impl Move {
    fn new(stitch: MoveStitch, highlight: Highlight) -> Self {
        Self { stitch, highlight }
    }
}

impl StitchCommand {
    fn row_to_stitches(chain: Highlight, row: &[Move]) -> Result<Vec<Self>> {
        fn arbitrary_push(nexts: &mut Vec<Vec<(usize, Highlight)>>, index: usize, value: (usize, Highlight)) {
            while nexts.len() <= index {
                if nexts.len() == index {
                    nexts.push(vec![value]);
                    return;
                } else {
                    nexts.push(Vec::new());
                }
            }
            if let Err(jndex) = nexts[index].binary_search_by_key(&value.0, |v| v.0) {
                nexts[index].insert(jndex, value);
            }
        }

        let total_nexts = row.iter().map(|v| (v.stitch == MoveStitch::Next) as usize).sum::<usize>();
        let total_currs = row.len() - total_nexts;

        let mut nexts = Vec::new();
        let mut next = 0;
        let mut curr = 0;
        let mut connected_nexts = vec![(0, chain)];
        let mut connected_currs = vec![(0, chain)];
        for item in row {
            if item.highlight == chain { continue; }
            match item.stitch {
                MoveStitch::Curr => {
                    if let Some(&(index, highlight)) = connected_currs.iter().min_by_key(|(_, highlight)| (highlight.0.pos - highlight.1.pos).magnitude_squared().ord()) {
                        arbitrary_push(&mut nexts, index, (curr, highlight))
                    }
                    curr += 1;
                    // if curr < total_currs {
                    //     connected_nexts.push((curr, item.highlight));
                    // }
                    connected_nexts.push((curr, item.highlight));
                    connected_currs.clear();
                },
                MoveStitch::Next => {
                    if let Some(&(index, highlight)) = connected_nexts.iter().min_by_key(|(_, highlight)| (highlight.0.pos - highlight.1.pos).magnitude_squared().ord()) {
                        arbitrary_push(&mut nexts, next, (index, highlight))
                    }
                    next += 1;
                    if next < total_nexts {
                        connected_currs.push((next, item.highlight));
                    }
                    connected_nexts.clear();
                },
            }
        }

        // Program hasn't realised that we have finished yet, so flush remaining data.
        if let Some(&(index, highlight)) = connected_currs.iter().min_by_key(|(_, highlight)| (highlight.0.pos - highlight.1.pos).magnitude_squared().ord()) {
            arbitrary_push(&mut nexts, index, (curr, highlight))
        }

        if let Some(&(index, highlight)) = connected_nexts.iter().min_by_key(|(_, highlight)| (highlight.0.pos - highlight.1.pos).magnitude_squared().ord()) {
            arbitrary_push(&mut nexts, next, (index, highlight))
        }

        // Preprocess to remove zig-zags
        let mut popped = 0;
        for (next, next_stitch) in nexts.clone().iter().enumerate() {
            let Some((curr, _)) = next_stitch.last() else {
                return Err(failed_assert_internal::<17>(None))
            };
            if next_stitch.len() - popped == 1 {
                if let Some(vh) = nexts.get_mut(next + 1) &&
                vh.first().map(|(curr, _)| curr) == Some(curr) &&
                vh.len() >= 2 {
                    vh.remove(0);
                    popped = 1;
                    continue;
                }
            } else {
                if let Some(vh) = nexts.get(next + 1) &&
                vh.first().map(|(curr, _)| curr) == Some(curr) {
                    nexts[next].pop();
                }
            }
            popped = 0;
        }

        let mut result = Vec::new();
        for (next, next_stitch) in nexts.iter().enumerate() {
            if next_stitch.len() >= 2 {
                result.push(StitchCommand::Dec(next_stitch.len() - 1, next_stitch.iter().map(|(_, highlight)| *highlight).collect()));
            } else if let Some(vh) = nexts.get(next + 1).cloned() &&
            vh.first().map(|(curr, _)| curr) == Some(&next_stitch.first().unwrap().0) {
                continue;
            } else {
                let mut backwards = next;
                let mut end_found = false;
                let stitch = next_stitch.first().unwrap();
                let mut highlights = VecDeque::from(vec![stitch.1]);
                let curr = stitch.0;
                while backwards > 0 && !end_found {
                    backwards -= 1;
                    let back_stitch = nexts[backwards].last().unwrap();
                    if back_stitch.0 == curr {
                        highlights.push_front(back_stitch.1);
                    } else {
                        end_found = true;
                    }
                }
                result.push(StitchCommand::Inc(highlights.len(), highlights.into()));
            }
        }

        Ok(result)
    }

    pub fn from_internal(stitches: Vec<InternalStitchCommand>, magic_circle: usize, magic_highlights: Vec<Highlight>) -> Result<Vec<Self>> {
        use InternalStitchCommand as ISC;
        use MoveStitch::*;
        let mut result = vec![Self::MagicCircle(magic_circle, magic_highlights)];
        let ISC::NextRow(_, mut chain) = stitches[0] else { panic!("Impossible") };
        let mut currv = Vec::new();
        for stitch in stitches {
            let moving = match stitch {
                ISC::MoveCurr(highlight) => Move::new(Curr, highlight),
                ISC::MoveNext(highlight) => Move::new(Next, highlight),
                ISC::NextRow(ss, next_chain) => {
                    if !currv.is_empty() {
                        result.append(&mut Self::row_to_stitches(chain, &currv)?);
                        currv.clear();
                    }
                    chain = next_chain;
                    result.push(Self::NextRow(vec![ss]));
                    continue;
                }
            };
            currv.push(moving);
        }

        // println!("{:?}", currv.iter().map(|m| m.stitch).collect::<Vec<_>>());
        result.append(&mut Self::row_to_stitches(chain, &currv)?);
        
        Ok(result)
    }
}

impl Processor {
    pub fn display_from_value(&self, display: &StitchDisplay, index: Option<usize>) -> String {
        let (string, highlights) = display.highlight_value(index);

        self.sender.send(DisplayCommand::Clear(Group::HighlightedStitch)).unwrap();

        for highlight in highlights {
            self.sender.send(DisplayCommand::Edge {
                a: highlight.0.pos,
                b: highlight.1.pos,
                thickness: self.model.radius * 0.02,
                colour: Srgba::RED,
                depth: false,
                group: Group::HighlightedStitch
            }).unwrap();
            self.sender.send(DisplayCommand::Point {
                pos: highlight.0.pos,
                radius: self.model.radius * 0.02,
                colour: Srgba::RED,
                depth: false,
                group: Group::HighlightedStitch
            }).unwrap();
            self.sender.send(DisplayCommand::Point {
                pos: highlight.1.pos,
                radius: self.model.radius * 0.02,
                colour: Srgba::RED,
                depth: false,
                group: Group::HighlightedStitch
            }).unwrap();
        }

        string
    }

    pub fn overwrite_debug_stitches(&self, display: &StitchDisplay) {
        self.sender.send(DisplayCommand::ClearAllExcept(vec![Group::StitchFace, Group::StitchRow, Group::Seam])).unwrap();
        let seed = self.get_info_unwrapped().seed_point;
        self.sender.send(DisplayCommand::Point {
            pos: seed,
            radius: self.model.radius * 0.02,
            colour: Srgba::BLUE,
            depth: true,
            group: Group::Seed
        }).unwrap();

        for highlight in display.iter().flat_map(|(_, highlight, _)| highlight) {
            self.sender.send(DisplayCommand::Edge {
                a: highlight.0.pos,
                b: highlight.1.pos,
                thickness: self.model.radius * 0.015,
                colour: Srgba::new(80, 80, 0, 192),
                depth: true,
                group: Group::Stitch
            }).unwrap()
        }
    }
}

pub enum StitchFormatter {
    StitchPoint(Vec<(StitchPointFormat, Vec<Highlight>)>),
    Worded(Vec<(WordedFormat, Vec<Highlight>)>),
    CrochetParade(Vec<(CrochetParadeFormat, Vec<Highlight>)>),
}

impl StitchFormatter {
    fn from_intermediate(format: StitchFormatChoice, vec: Vec<StitchCommand>, metadata: Metadata) -> Self {
        match format {
            StitchFormatChoice::StitchPoint => Self::StitchPoint(StitchPointFormat::from_intermediate(vec.into())),
            StitchFormatChoice::Worded => Self::Worded(WordedFormat::from_intermediate(vec.into(), metadata)),
            StitchFormatChoice::CrochetParade => Self::CrochetParade(CrochetParadeFormat::from_intermediate(vec.into(), metadata)),
        }
    }
}

pub struct Metadata {
    pub final_highlights: Vec<StitchPoint>,
    pub calculator: FixedHookCalculator,
}

pub struct StitchDisplay {
    vec: Vec<(String, Vec<Highlight>, HighlightConf)>,
    seperator: &'static str
}

impl StitchDisplay {
    fn from_formatter(formatter: StitchFormatter) -> Self {
        let (vec, seperator) = match formatter {
            StitchFormatter::StitchPoint(items) => (
                items.into_iter().map(|(v, h)| (v.to_string(), h, v.get_conf())).collect(),
                StitchPointFormat::SEPERATOR
            ),
            StitchFormatter::Worded(items) => (
                items.into_iter().map(|(v, h)| (v.to_string(), h, v.get_conf())).collect(),
                WordedFormat::SEPERATOR
            ),
            StitchFormatter::CrochetParade(items) => (
                items.into_iter().map(|(v, h)| (v.to_string(), h, v.get_conf())).collect(),
                CrochetParadeFormat::SEPERATOR
            ),
        };

        Self { vec, seperator }
    }

    pub fn from_internal(format: StitchFormatChoice, vec: Vec<StitchCommand>, metadata: Metadata) -> Self {
        let formatter = StitchFormatter::from_intermediate(format, vec, metadata);
        Self::from_formatter(formatter)
    }

    pub fn highlight_value(&self, index: Option<usize>) -> (String, Vec<Highlight>) {
        let mut result_str = String::new();
        let mut result_highlights = Vec::new();
        for (i, (string, highlights, config)) in self.vec.iter().enumerate() {
            result_str.push_str(&config.prefix);
            if Some(i) == index {
                #[cfg(target_arch = "wasm32")]
                result_str.push_str(&format!("<b>&lt;{}&gt;</b>", string));
                #[cfg(not(target_arch = "wasm32"))]
                result_str.push_str(&format!("<{}>", string).bold().to_string());
                result_highlights.append(&mut highlights.clone());
            } else {
                result_str.push_str(string);
            }
            result_str.push_str(&config.suffix);

            if config.seperator_follows && i != self.vec.len() - 1 && self.vec[i+1].2.seperator_predecesses {
                result_str.push_str(self.seperator);
            }
        }

        (result_str, result_highlights)
    }
}

impl Deref for StitchDisplay {
    type Target = Vec<(String, Vec<Highlight>, HighlightConf)>;

    fn deref(&self) -> &Self::Target {
        &self.vec
    }
}

impl DerefMut for StitchDisplay {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.vec
    }
}

impl Display for StitchDisplay {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.highlight_value(None).0)
    }
}

#[derive(Clone)]
pub struct HighlightConf {
    /// This is not highlighted
    prefix: String,
    /// This is not highlighted
    suffix: String,
    seperator_predecesses: bool,
    seperator_follows: bool,
}

impl HighlightConf {
    pub fn new(prefix: String, suffix: String, seperator_predecesses: bool, seperator_follows: bool) -> Self {
        Self { prefix, suffix, seperator_predecesses, seperator_follows }
    }

    // pub fn no_seperator() -> Self {
    //     Self { seperator_follows: false, ..Default::default() }
    // }

    pub fn space_seperator() -> Self {
        Self { prefix: String::new(), suffix: " ".to_string(), seperator_predecesses: true, seperator_follows: false}
    }
}

impl Default for HighlightConf {
    fn default() -> Self {
        Self { prefix: String::new(), suffix: String::new(), seperator_predecesses: true, seperator_follows: true }
    }
}